(275460, 18380, 6230, '<td valign="top">Great colours but where is the challenge subject???</td>', 'Great colours but where is the challenge subject???', '2003-04-23 14:25:13.000000', NULL, 1),
(275461, 18380, 5822, '<td valign="top">The colors are great and stand out well against the darker background. Lighting is good too. Very well done.</td>', 'The colors are great and stand out well against the darker background. Lighting is good too. Very well done.', '2003-04-23 14:25:57.000000', NULL, 1),
(275462, 19107, 7890, '<td valign="top">This would be great for the transportion challenge, good shot for this one to.</td>', 'This would be great for the transportion challenge, good shot for this one to.', '2003-04-23 14:26:18.000000', NULL, 1),
