(275467, 18888, 7890, '<td valign="top">fantastic shot,  great job!</td>', 'fantastic shot,  great job!', '2003-04-23 14:28:47.000000', NULL, 1),
(275471, 19009, 7890, '<td valign="top">how cute, a few hot spots on this one,  but excellent entry.</td>', 'how cute, a few hot spots on this one,  but excellent entry.', '2003-04-23 14:30:58.000000', NULL, 1),
(275472, 18565, 117, '<td valign="top">might be a little bright wish you could burn here still a excellent image and capture-10</td>', 'might be a little bright wish you could burn here still a excellent image and capture-10', '2003-04-23 14:31:13.000000', NULL, 1),
